<script module lang="ts">
/**
 * The only component that renders icons (`design/components/icon.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/icon.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */

import Glyph from './Glyph.svelte'
import { joinSlot } from '../conventions/slotted.svelte'
import type { IconRole } from '@polymorph/engine'
import styles from './icon.module.css'

export interface IconProps {
  /**
   * Accessible name: set it for a meaningful icon (`role="img"` + `aria-label`), omit it for a
   * decorative one (`aria-hidden`), and omit it inside an icon-only Button, which uses its own
   * `label`.
   */
  label?: string
  /**
   * A meaning from the closed role enum, never a glyph name.
   */
  name: IconRole
  size?: 'sm' | 'md' | 'lg'
}
</script>

<script lang="ts">
let { label: labelOwn, name, size = 'md' }: IconProps = $props()
const joined = joinSlot(undefined, () => ({ label: labelOwn, name: name, size: size }))
const label = $derived(
  joined.passed['label'] === undefined ? labelOwn : (joined.passed['label'] as typeof labelOwn),
)
const meaningful = $derived(label !== undefined)
</script>

{@render joined.start?.()
}{#if joined.shown
  }<Glyph
    class={styles.icon}
    glyph={name}
    data-size={size}
    data-icon={name}
    aria-hidden={(!meaningful) ? true : undefined}
    role={(meaningful) ? 'img' : undefined}
    aria-label={label}
    data-member="icon"
/>{/if
}{@render joined.end?.()}
